const duration = n => n == null ? 'Not reached' : `${Math.floor(n/60)}m ${Math.round(n%60)}s`;
const seatPosition = (i,n) => {const a=Math.PI/2+2*Math.PI*i/Math.max(n,1);return `left:calc(50% + ${42*Math.cos(a)}% * var(--seat-spread-x,1));top:${50+44*Math.sin(a)}%`};
// Bets sit on their own inner ring. Keep this far enough inside the seat ring
// that the marker cannot be covered by the cards extending above a player box.
const betPosition = (i,n) => {
 const a=Math.PI/2+2*Math.PI*i/Math.max(n,1),belowCenter=Math.sin(a)>0;
 // Cards extend above every player box. Lower seats therefore need more
 // inward clearance in both axes; elsewhere the bet can sit nearer its player.
 const horizontalRadius=belowCenter?20:30,verticalRadius=belowCenter?16:29;
 return `left:${50+horizontalRadius*Math.cos(a)}%;top:${50+verticalRadius*Math.sin(a)}%`;
};
const playingCard = (value, back=false) => {
 if(back)return '<i class="playing-card back" aria-label="Face-down card"></i>';
 const raw=String(value||'').trim(),rank=raw.slice(0,-1).toUpperCase().replace('T','10'),suit=raw.slice(-1).toLowerCase();
 const suits={s:'♠',h:'♥',d:'♦',c:'♣'},red=suit==='h'||suit==='d';
 return `<i class="playing-card ${red?'red':'black'}" aria-label="${esc(raw)}"><b>${esc(rank)}</b><span>${suits[suit]||esc(suit)}</span></i>`;
};
const gameHoleCardCount = (game,players=[]) => {
 const known=Math.max(0,...players.map(p=>p.cards?.length||0));
 return known||({PLO5:5,PLO4:4,NLH:2}[String(game||'').toUpperCase()]||2);
};
// Seconds left for the acting seat, counted from the snapshot: EvenBet's move time first, then its time bank.
const actingClock = (clock,captured) => {
 if(!clock||!captured)return null;
 const stamp=Date.parse(captured+(/Z$|[+-]\d\d:\d\d$/.test(captured)?'':'Z'));if(!stamp)return null;
 const elapsed=Number(clock.age||0)+(Date.now()-stamp)/1000,move=Number(clock.move_seconds||0)-elapsed,bank=Number(clock.bank_seconds||0);
 if(move>0)return {seat:clock.seat,text:`${Math.ceil(move)}s${bank>0?` · +${Math.round(bank)}s bank`:''}`,cls:move<=5?'low':''};
 const left=Number(clock.move_seconds||0)>0?bank+move:bank-elapsed;
 return left>0?{seat:clock.seat,text:`Time bank ${Math.ceil(left)}s`,cls:left<=5?'bank low':'bank'}:{seat:clock.seat,text:'Time is up',cls:'low'};
};
const pokerTableView = ({players,maxSeats,game,board,pot,street,dealerSeat,actingSeat,actingTimer=null,className='',formatAmount=v=>Number(v).toFixed(2)}) => {
 const n=Math.max(maxSeats||0,players.length,1),backs=gameHoleCardCount(game,players);
 const seats=players.map(p=>{const toAct=actingSeat!==null&&actingSeat!==undefined&&Number(p.seat)===Number(actingSeat),cards=(p.cards||[]).map(c=>playingCard(c)).join(''),hidden=p.hidden?Array.from({length:backs},()=>playingCard('',true)).join(''):'';return `<div class="replay-seat ${p.hero?'hero':''} ${p.folded?'folded':''} ${toAct?'to-act':''} ${p.winner?'winner':''}" data-seat="${p.seat}" style="${seatPosition(p.seat,n)}" ${toAct?'title="To act" aria-label="'+esc(p.name)+' — to act"':''}><div class="seat-cards">${cards}${hidden}</div>${p.actionText?`<em class="replay-action-bubble">${esc(p.actionText)}</em>`:''}<strong>${esc(p.name)}</strong><span>${esc(formatAmount(p.stack))}</span>${toAct&&actingTimer&&Number(actingTimer.seat)===Number(p.seat)?`<b class="seat-timer ${actingTimer.cls}" aria-live="off">${esc(actingTimer.text)}</b>`:''}${Number(p.seat)===Number(dealerSeat)?'<i class="dealer-button">D</i>':''}</div>`}).join('');
 const bets=players.filter(p=>Number(p.bet)>0).map(p=>`<div class="table-bet" data-seat="${p.seat}" style="${betPosition(p.seat,n)}">${esc(formatAmount(p.bet))}</div>`).join('');
 return `<div class="poker-replay live-felt ${className}">${seats}${bets}<div class="replay-center"><div class="cards board">${(board||[]).map(c=>playingCard(c)).join('')}</div><strong>Pot ${esc(formatAmount(pot))}</strong><span>${esc(street)}</span></div></div>`;
};
const entryTrendChart = d => {
 const points=d.points||[];if(!points.length)return empty('No entry history','There are no chart points in this period.');
 const W=900,H=280,pad=44,max=Math.max(1,...points.flatMap(p=>[p.scheduled,p.running,p.humans||0])),first=+new Date(points[0].at),last=+new Date(points.at(-1).at),span=Math.max(1,last-first);
 const x=p=>pad+(+new Date(p.at)-first)/span*(W-pad*2),y=v=>H-pad-v/max*(H-pad*2),path=key=>points.map((p,i)=>{
  const at=x(p).toFixed(2);
  if(p[key]==null)return i&&points[i-1][key]!=null?`H${at}`:'';
  const step=i&&points[i-1][key]!=null;
  return step?`H${at}V${y(p[key]).toFixed(2)}`:`M${at},${y(p[key]).toFixed(2)}`;
 }).join(' '),fmt=v=>new Date(v).toLocaleString(undefined,{timeZone:d.timezone,...(span>86400000?{month:'short',day:'numeric'}:{}),hour:'2-digit',minute:'2-digit',hour12:false});
 return `<div class="entry-chart-wrap"><div class="entry-chart-tools"><span>Hover for time and counts. Select two points to measure a change.</span><button class="button small entry-zoom" disabled>Zoom to selection</button><button class="button small entry-reset">Reset view</button></div><svg class="entry-chart" viewBox="0 0 ${W} ${H}" tabindex="0" role="img" aria-label="Scheduled versus running bot entries. Use arrow keys to inspect and Enter to select two points.">${[0,.25,.5,.75,1].map(f=>`<line x1="${pad}" y1="${y(max*f)}" x2="${W-pad}" y2="${y(max*f)}"/><text x="7" y="${y(max*f)+4}">${Math.round(max*f)}</text>`).join('')}<rect class="entry-selection" x="0" y="${pad}" width="0" height="${H-pad*2}"/><path class="scheduled" d="${path('scheduled')}"/><path class="running" d="${path('running')}"/>${d.human_seats?`<path class="human-seats" style="fill:none;stroke:#963d83;stroke-width:2.5" d="${path('humans')}"/>`: ''}${Array.from({length:7},(_,i)=>{const stamp=first+span*i/6,px=pad+(W-pad*2)*i/6;return `<text class="axis-label ${i%2?'minor ':''}${i===0?'':i===6?'end':'middle'}" x="${px}" y="${H-8}">${esc(fmt(stamp))}</text>`}).join('')}<line class="entry-crosshair" x1="${W-pad}" x2="${W-pad}" y1="${pad}" y2="${H-pad}"/></svg><div class="entry-readout"></div><div class="entry-comparison">Click a starting point, then an ending point to compare entry counts and elapsed time.</div><div class="entry-chart-legend"><span><i class="running"></i>${d.format&&d.format!=='RING'?'Registered or playing':'Actually running'}</span><span><i class="scheduled"></i>Scheduled target</span>${d.human_seats?'<span><i style="border-color:#963d83"></i>Human seats (sampled average)</span>':''}<small>${esc(d.timezone)} · recorded entry changes</small></div>${d.human_seats?`<p class="sub">${esc(d.human_seats.note)} Values are averages over ${d.human_seats.step_minutes}-minute intervals with valid samples.</p>`:''}</div>`;
};
const attachEntryTrendChart = (root,data) => {
 let view=data,selected=[],index=0;
 const time=value=>new Date(value).toLocaleString(undefined,{timeZone:data.timezone,month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});
 const draw=()=>{
  root.innerHTML=entryTrendChart(view);const points=view.points||[];if(!points.length)return;
  const svg=$('svg',root),first=+new Date(points[0].at),span=Math.max(1,+new Date(points.at(-1).at)-first),px=p=>44+(+new Date(p.at)-first)/span*812;
  const inspect=i=>{index=Math.max(0,Math.min(points.length-1,i));const p=points[index],line=$('.entry-crosshair',root);line.setAttribute('x1',px(p));line.setAttribute('x2',px(p));$('.entry-readout',root).textContent=`${time(p.at)} | Running: ${p.running} | Scheduled: ${p.scheduled ?? 'unknown'}${view.human_seats?` | Human seats (sampled average): ${p.humans==null?'unknown':`${p.human_partial?'≥':''}${p.humans}`}`:''}`;};
  const choose=()=>{
   if(selected.length===2)selected=[];selected.push(points[index]);
   const box=$('.entry-selection',root);box.setAttribute('x',px(selected[0]));box.setAttribute('width','0');
   $('.entry-zoom',root).disabled=true;
   if(selected.length===1){$('.entry-comparison',root).textContent=`Start: ${time(selected[0].at)} | ${selected[0].running} running. Select an ending point.`;return;}
   selected.sort((a,b)=>+new Date(a.at)-+new Date(b.at));const [a,b]=selected,seconds=Math.round((+new Date(b.at)-+new Date(a.at))/1000),change=b.running-a.running;
   box.setAttribute('x',px(a));box.setAttribute('width',px(b)-px(a));
   $('.entry-comparison',root).textContent=`${time(a.at)} to ${time(b.at)} | ${a.running} to ${b.running} running (${change>0?'+':''}${change}) in ${Math.floor(seconds/60)} min ${seconds%60} sec`;
   $('.entry-zoom',root).disabled=seconds===0;
  };
  const locate=event=>{const matrix=svg.getScreenCTM();if(!matrix)return;const point=svg.createSVGPoint();point.x=event.clientX;point.y=event.clientY;const stamp=first+(point.matrixTransform(matrix.inverse()).x-44)/812*span;let low=0,high=points.length-1;while(low<high){const mid=Math.floor((low+high)/2);if(+new Date(points[mid].at)<stamp)low=mid+1;else high=mid;}inspect(low>0&&stamp-(+new Date(points[low-1].at))<(+new Date(points[low].at))-stamp?low-1:low);};
  svg.onpointermove=locate;svg.onclick=event=>{locate(event);choose();};
  svg.onkeydown=event=>{if(['ArrowLeft','ArrowRight','Enter',' '].includes(event.key)){event.preventDefault();if(event.key==='ArrowLeft')inspect(index-1);else if(event.key==='ArrowRight')inspect(index+1);else choose();}};
  $('.entry-zoom',root).onclick=()=>{const [a,b]=selected;view={...data,points:data.points.filter(p=>+new Date(p.at)>=+new Date(a.at)&&+new Date(p.at)<=+new Date(b.at))};selected=[];draw();};
  $('.entry-reset',root).onclick=()=>{view=data;selected=[];draw();};inspect(points.length-1);
 };draw();
};
const machineMetricChart = d => {
 const points=d.points||[];if(!points.length)return `<div class="machine-chart-empty">No resource samples in the last ${d.hours} hours.</div>`;
 const W=700,H=235,left=38,right=42,top=12,bottom=34,first=new Date(points[0].at).getTime(),last=new Date(points.at(-1).at).getTime(),span=Math.max(1,last-first),maxEntries=Math.max(1,...points.map(p=>Number(p.entries)||0));
 const x=p=>left+(new Date(p.at).getTime()-first)/span*(W-left-right),pct=v=>H-bottom-Number(v)/100*(H-top-bottom),entry=v=>H-bottom-(Number(v)||0)/maxEntries*(H-top-bottom);
 const path=(key,scale)=>points.filter(p=>p[key]!=null).map((p,i)=>`${i?'L':'M'}${x(p).toFixed(1)},${scale(p[key]).toFixed(1)}`).join(' '),fmt=v=>new Date(v).toLocaleTimeString(undefined,{timeZone:state.site.timezone,hour:'2-digit',minute:'2-digit'}),mid=points[Math.floor((points.length-1)/2)];
 return `<div class="machine-chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="CPU, memory and bot entries during the last ${d.hours} hours">${[0,25,50,75,100].map(v=>`<line x1="${left}" y1="${pct(v)}" x2="${W-right}" y2="${pct(v)}"/><text x="3" y="${pct(v)+4}">${v}%</text>`).join('')}<text class="right-axis" x="${W-3}" y="${entry(maxEntries)+4}">${maxEntries}</text><text class="right-axis" x="${W-3}" y="${entry(0)+4}">0</text><path class="cpu" d="${path('cpu',pct)}"/><path class="memory" d="${path('memory',pct)}"/><path class="entries" d="${path('entries',entry)}"/><text class="time" x="${left}" y="${H-8}">${esc(fmt(points[0].at))}</text><text class="time middle" x="${W/2}" y="${H-8}">${esc(fmt(mid.at))}</text><text class="time end" x="${W-right}" y="${H-8}">${esc(fmt(points.at(-1).at))}</text></svg><div class="machine-chart-legend"><span><i class="cpu"></i>CPU</span><span><i class="memory"></i>RAM</span><span><i class="entries"></i>Bot entries (right axis)</span><small>${d.sample_minutes}-minute samples · last ${d.hours}h</small></div></div>`;
};
