async function init(){
  try {
    state.me=await api('me');
    if(!state.me.memberships.length){login('Your access is pending.');$('.login-box').innerHTML=`<h2>Request workspace access</h2><p>Signed in as ${esc(state.me.user.name)}. An administrator needs to link this Microsoft identity to Nenad.</p>${button('Request access','request',true)}<p class="sub">Identity: <code class="break-word">${esc(state.me.user.subject)}</code></p><a href="/.auth/logout">Sign out</a>`;$('#request').onclick=async()=>{await api('access-request','POST',{});toast('Access request recorded');};return;}
    const query=new URLSearchParams(location.search);state.customer=state.me.memberships.find(m=>m.id===+query.get('customer_id'))||state.me.memberships[0];state.sites=(await api('sites')).items;state.site=state.sites.find(s=>s.id===+(new URLSearchParams(location.search).get('site_id')))||state.sites[0];
    const liveRequest=new URLSearchParams(location.search).get('live_request');if(liveRequest){await liveTableWindow(liveRequest);return;}
    shell(); await navigate();
  }catch(e){login(e.message.includes('Sign in')?'Your workspace, in one place.':e.message);}
}
