// A time in the site's zone: just the clock today, the weekday and date otherwise.
const shortTime=v=>{if(!v)return '';const zone=state.site?.timezone,d=new Date(v),day=x=>new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(x),clock=new Intl.DateTimeFormat(undefined,{timeZone:zone,hour:'2-digit',minute:'2-digit'}).format(d);return day(d)===day(new Date())?clock:`${new Intl.DateTimeFormat(undefined,{timeZone:zone,weekday:'short',day:'numeric',month:'short'}).format(d)} ${clock}`;};
