 if(!render(gen,`Only tables observed during the last 3 minutes are shown. Lobby snapshots refresh every ${d.refresh_seconds} seconds.`,`<div class="live-filters">${select('Game format','live-game',state.tableFilters.game,[['all','All games'],['NLH','NLH'],['PLO4','PLO4'],['PLO5','PLO5']])}${select('Table type','live-type',state.tableFilters.type,[['all','All types'],['RING','Ring'],['SNG','SNG'],['MTT','MTT']])}${select('MTTs','live-mtt',state.tableFilters.mtt,[['early','Early registration started'],['all','All MTTs']])}<span id="live-table-count"></span></div><div id="live-table-results"></div>`))return;
 const openLive=b=>{const table=d.items.find(t=>String(t.id)===b.dataset.liveTable),bots=table.players.filter(p=>p.account_id);modal(`Live · ${table.name}`,select('View as bot','account_id',bots[0].account_id,bots.map(p=>[p.account_id,`${p.username} · ${p.machine||`machine ${p.machine_id}`}`]))+'<p class="sub">While the new window remains open, that bot’s machine publishes table state as soon as it changes. The feed stops within 45 seconds after the window closes. Only the selected hero’s hole cards are included, plus cards opponents show at showdown.</p>',async v=>{const popup=window.open('about:blank','_blank');try{const r=await siteApi('tables/live','POST',{table_id:table.id,account_id:+v.account_id});popup.location=`/?customer_id=${state.customer.id}&site_id=${state.site.id}&live_request=${encodeURIComponent(r.request_id)}`;}catch(e){popup.close();throw e;}},'Open live window');};
 const draw=()=>{const f=state.tableFilters,items=d.items.filter(t=>(f.game==='all'||t.game===f.game)&&(f.type==='all'||t.table_type===f.type)&&(f.mtt==='all'||t.table_type!=='MTT'||t.early_registration_started!==false)).sort(liveTableOrder);$('#live-table-count').textContent=`${items.length} of ${d.items.length} tables`;$('#live-table-results').innerHTML=items.length?`<div class="lobby-grid">${items.map(t=>t.table_type!=='RING'?tournamentCard(t):`<article class="lobby-table"><div class="top"><div><h2>${esc(t.name)}</h2><span>${esc(t.game)} · ${esc(t.table_type)} · ${esc(t.currency)} · BB ${t.big_blind}</span></div>${pill(`${t.bot_entries} bots`,'green')}</div><div class="lobby-seats">${Array.from({length:t.seats},(_,i)=>{const p=t.players.find(x=>Number(x.seat)===i),kind=p?.account_id?'bot':p?'human':'free';return `<i class="${kind}" style="${seatPosition(i,t.seats)}" title="Seat ${i+1}: ${p?esc(p.username)+(p.account_id?' (bot)':' (human)'):'Free'}" aria-label="Seat ${i+1}: ${p?esc(p.username)+(p.account_id?' bot':' human'):'free'}"></i>`}).join('')}</div><div class="table-meta"><strong>${t.occupied} / ${t.seats} players</strong><span>${t.bot_entries} bots seated</span></div><div class="lobby-foot"><span></span>${t.players.some(p=>p.account_id)?`<button class="button small" data-live-table="${esc(t.id)}">Open Live</button>`:'<span>No active bot</span>'}</div></article>`).join('')}</div>`:card('Lobby',empty(d.items.length?'No matching tables':'No current lobby observations',d.items.length?'Change or clear a filter to see other live tables.':'No table has been observed during the last 60 seconds. Start the PokerController machine worker to publish live lobby data.'));document.querySelectorAll('[data-live-table]').forEach(b=>b.onclick=()=>openLive(b));document.querySelectorAll('[data-registered]').forEach(b=>b.onclick=()=>showRegistered(d.items.find(t=>String(t.id)===b.dataset.registered)));};
 const showRegistered=t=>{const bots=t.bots||[],running=t.tournament_state==='running',names=state=>bots.filter(b=>b.state===state).sort((a,b)=>a.username.localeCompare(b.username,undefined,{sensitivity:'base'})),group=(title,list)=>list.length?`<h3>${title} <span class="sub">${list.length}</span></h3><ol class="registered-list">${list.map(b=>`<li>${esc(b.username)}${b.ticket?' <span class="sub" title="Registered by the site with a satellite ticket">· satellite ticket</span>':''}${b.place?` <span class="sub">· place ${b.place}</span>`:''}</li>`).join('')}</ol>`:'',dialog=$('#dialog');dialog.innerHTML=`<form method="dialog"><div class="dialog-head"><h2>Bots · ${esc(t.name)}</h2><button class="icon-button" value="close">×</button></div><div class="dialog-content">${(()=>{const reg=names('in').length+names('out').length,pend=names('pending').length,left=Math.max(0,(t.plan_total||0)-reg-pend);return `<p class="sub">${t.plan_total?`Plan: <strong>${t.plan_total}</strong> bots · ${reg} registered · ${pend} sent to a PC, not confirmed · ${left} still to be scheduled (the plan spreads them over early and late registration)`:'No bot plan for this MTT'}</p>`;})()}${group(running?'Still playing':'Registered',names('in'))}${group('Out',names('out'))}${group('Sent to a PC, not confirmed yet',names('pending'))}</div><div class="dialog-footer"><button class="button" value="close">Close</button></div></form>`;dialog.showModal();};
